// Cloudflare Worker: lets the site's ateliers use Claude without a claude.ai account.
// The page sends { prompt, tier } (plus { kb: true, query } to ground the answer in the course);
// the Worker calls the Claude API with the secret key (Worker secret ANTHROPIC_API_KEY)
// and returns the JSON object Claude wrote.
import Anthropic from "@anthropic-ai/sdk";
// Text of every lesson of the site + BM25 index, generated by ia-proxy/build/build_kb.py
import KB from "./kb.json";

// Model used to GENERATE exercises (ateliers, TCF subjects): quality matters, volume is low.
const MODEL = "claude-opus-5-5";
// Model used to ANSWER students' questions: high volume, so the cheapest one.
// Haiku 5.5 is $0.10/$0.50 per MTok against Opus 5.5's $4/$20 — about 40x less.
const MODEL_CHAT = "claude-haiku-5-5";
const CHAT_MAX_TOKENS = 1200;   // a tutor's answer, not an essay
const CHAT_HISTORY = 6;         // turns kept, oldest dropped
const MAX_QUESTION_CHARS = 2000;
const ALLOWED_ORIGINS = ["https://karla19urios.github.io", "http://localhost:8000"];
const MAX_PROMPT_CHARS = 12000;
const MAX_QUERY_CHARS = 6000;
const KB_RESULTS = 12;          // excerpts sent to Claude
const KB_PER_PAGE = 2;          // at most this many excerpts from the same lesson
const KB_ON_PAGE = 3;           // excerpts forced in from the lesson the student has open

// ---------- course knowledge base (same tokenizer as build_kb.py) ----------
const STOP = new Set(("je tu il elle nous vous ils elles on le la les l un une des de du d et ou est sont a ai as ont pas ne n ce cet cette ces c se s sa son ses mon ma mes ton ta tes leur leurs notre nos votre vos pour dans sur avec par au aux plus tres bien mais si qu " +
  "the of and to is in it you for are with this that").split(" "));
function tokens(text) {
  const plain = text.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const out = [];
  for (let t of plain.match(/[a-z]+/g) || []) {
    if (STOP.has(t)) continue;
    if (t.length < 2 && t !== "y") continue;
    if (t.length > 4 && (t.endsWith("s") || t.endsWith("x"))) t = t.slice(0, -1);
    out.push(t);
  }
  return out;
}
// The map holds absolute, percent-encoded URLs; the page sends location.href.
// Compare decoded pathnames so encoding differences don't hide the match.
function pageIndex(url) {
  if (!url) return -1;
  const norm = (u) => {
    try { return decodeURIComponent(new URL(u, "https://karla19urios.github.io/").pathname); }
    catch (e) { return String(u); }
  };
  const want = norm(url);
  return KB.map.findIndex((m) => m.u && norm(m.u) === want);
}

function searchCourse(query, onPage) {
  const N = KB.chunks.length, k1 = 1.2, b = 0.75, scores = new Map();
  for (const t of new Set(tokens(query))) {
    const post = KB.idx[t];
    if (!post) continue;
    const df = post.length / 2, idf = Math.log(1 + (N - df + 0.5) / (df + 0.5));
    for (let i = 0; i < post.length; i += 2) {
      const d = post[i], tf = post[i + 1];
      const s = idf * tf * (k1 + 1) / (tf + k1 * (1 - b + b * KB.lens[d] / KB.avg));
      scores.set(d, (scores.get(d) || 0) + s);
    }
  }
  const perPage = new Map(), picked = [], seen = new Set();
  // the lesson the student is actually looking at goes first, whatever BM25 thinks
  if (typeof onPage === "number" && onPage >= 0) {
    const here = [...scores.entries()].filter(([d]) => KB.chunks[d].p === onPage)
      .sort((x, y) => y[1] - x[1]);
    const fallback = here.length ? here : KB.chunks
      .map((c, d) => [d, 0]).filter(([d]) => KB.chunks[d].p === onPage);
    for (const [d] of fallback.slice(0, KB_ON_PAGE)) { picked.push(KB.chunks[d]); seen.add(d); }
    perPage.set(onPage, picked.length);
  }
  for (const [d] of [...scores.entries()].sort((x, y) => y[1] - x[1])) {
    if (seen.has(d)) continue;
    const p = KB.chunks[d].p;
    if ((perPage.get(p) || 0) >= KB_PER_PAGE) continue;
    perPage.set(p, (perPage.get(p) || 0) + 1);
    picked.push(KB.chunks[d]);
    if (picked.length >= KB_RESULTS) break;
  }
  return picked;
}
function courseContext(query) {
  const map = KB.map.map((m) => `- [${m.l}] ${m.t} — ${m.u}`).join("\n");
  const excerpts = searchCourse(query).map((c) => {
    const m = KB.map[c.p];
    return `<extrait lecon="${m.t}" niveau="${m.l}" section="${c.h}" url="${m.u}">\n${c.x}\n</extrait>`;
  }).join("\n");
  return "Documents du site du cours (les leçons que les étudiant·e·s suivent réellement).\n\n" +
    "<plan_du_site>\n" + map + "\n</plan_du_site>\n\n" +
    "<extraits_pertinents>\n" + excerpts + "\n</extraits_pertinents>\n\n" +
    "Appuie-toi en priorité sur ces leçons : reprends leurs règles, leurs exemples et leur terminologie, et reste cohérent·e avec elles. " +
    "Ignore les extraits qui ne concernent pas la demande. Quand tu recommandes des leçons, n'utilise que des URL qui figurent exactement dans <plan_du_site>.";
}

const SYSTEM =
  "Tu es l'assistant d'un site d'apprentissage du français (exercices, sujets d'entraînement TCF/TEF). " +
  "Tu ne réponds qu'à des demandes de génération de contenu pédagogique en français. " +
  "Réponds UNIQUEMENT avec l'objet JSON demandé, sans texte autour et sans balises markdown. " +
  "Si la demande n'a rien à voir avec l'apprentissage du français, réponds {\"error\":\"hors_sujet\"}.";

function cors(origin) {
  const ok = ALLOWED_ORIGINS.includes(origin);
  return {
    "Access-Control-Allow-Origin": ok ? origin : ALLOWED_ORIGINS[0],
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Max-Age": "86400",
    Vary: "Origin",
  };
}

function reply(origin, status, body) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", ...cors(origin) },
  });
}

function extractJson(text) {
  const t = text.trim().replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "");
  try { return JSON.parse(t); } catch (e) {}
  const a = t.indexOf("{"), b = t.lastIndexOf("}");
  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) {} }
  return null;
}


// ---------- students' questions (chat) ----------
// The site map is stable, so it sits in `system` behind a cache breakpoint: within one
// conversation every question after the first reads it from cache at a tenth of the price.
function siteMap() {
  return "Plan du site du cours — les seules leçons qui existent, avec leur URL exacte.\n\n" +
    KB.map.map((m) => `- [${m.l}] ${m.t} — ${m.u}`).join("\n");
}

function excerptsFor(question, pageUrl) {
  const picked = searchCourse(question, pageIndex(pageUrl));
  if (!picked.length) return "";
  return "<extraits_du_cours>\n" + picked.map((c) => {
    const m = KB.map[c.p];
    return `<extrait lecon="${m.t}" niveau="${m.l}" section="${c.h}" url="${m.u}">\n${c.x}\n</extrait>`;
  }).join("\n") + "\n</extraits_du_cours>";
}

const LANG_NAME = { es: "espagnol", en: "anglais", fr: "français" };

const SYSTEM_CHAT =
  "Tu es l'assistant du site de cours de français de Karla. Tu réponds aux questions des " +
  "étudiant·e·s pendant qu'ils font les exercices du site.\n\n" +
  "SUJETS. Tu n'aides que sur l'apprentissage du français (grammaire, vocabulaire, " +
  "prononciation, conjugaison, les exercices du site, la préparation du TCF et du TEF) et sur " +
  "l'utilisation du site. Pour tout le reste, dis gentiment en une phrase que tu n'aides que " +
  "sur le cours de français, et n'ajoute rien.\n\n" +
  "LANGUE. Réponds dans la langue de l'étudiant·e, indiquée à chaque question. Les exemples " +
  "en français restent en français ; tu peux les traduire entre parenthèses si c'est utile.\n\n" +
  "LONGUEUR. Sois bref : deux à six phrases, ou une petite liste. La personne est au milieu " +
  "d'un exercice, elle n'a pas demandé un cours magistral. Un exemple concret vaut mieux " +
  "qu'une explication abstraite.\n\n" +
  "LE COURS D'ABORD. Des extraits des leçons du site accompagnent chaque question. Appuie-toi " +
  "sur eux en priorité : reprends leurs règles, leur terminologie et leurs exemples, pour que " +
  "ce que tu dis ne contredise pas ce que la personne vient de lire. Si les extraits ne " +
  "couvrent pas la question, réponds avec tes propres connaissances, mais ne contredis jamais " +
  "une règle du cours.\n\n" +
  "LIENS. Quand tu renvoies à une leçon, n'utilise que des URL qui figurent exactement dans le " +
  "plan du site. N'invente jamais d'URL ni de titre de leçon.\n\n" +
  "PÉDAGOGIE. Si on te demande la réponse d'un exercice, ne la donne pas toute faite : " +
  "rappelle la règle, donne un indice, et invite à réessayer. Si la personne a déjà proposé " +
  "une réponse, dis si elle est juste et explique pourquoi. Corrige les fautes de français " +
  "dans la question seulement si la personne écrit en français et que la faute touche au sujet.\n\n" +
  "FORME. Texte simple. Tu peux utiliser **gras**, *italique* et des listes avec « - ». " +
  "Pas de titres, pas de tableaux, pas de blocs de code. N'inclus aucune balise XML interne " +
  "ou système dans ta réponse.";

async function chat(origin, env, body) {
  const question = typeof body.question === "string" ? body.question.trim() : "";
  if (!question || question.length > MAX_QUESTION_CHARS) return reply(origin, 400, { code: "bad_request" });
  const lang = LANG_NAME[body.lang] ? body.lang : "es";
  const page = body.page && typeof body.page === "object" ? body.page : {};
  const pageUrl = typeof page.url === "string" ? page.url.slice(0, 300) : "";
  const pageTitle = typeof page.title === "string" ? page.title.slice(0, 200) : "";

  const history = [];
  if (Array.isArray(body.history)) {
    for (const h of body.history.slice(-CHAT_HISTORY)) {
      const text = h && typeof h.text === "string" ? h.text.slice(0, MAX_QUESTION_CHARS) : "";
      if (!text) continue;
      history.push({ role: h.role === "assistant" ? "assistant" : "user", content: text });
    }
    while (history.length && history[0].role === "assistant") history.shift();
  }

  const situation = (pageTitle ? `Leçon ouverte : ${pageTitle}${pageUrl ? ` (${pageUrl})` : ""}\n` : "") +
    `Langue de l'étudiant·e : ${LANG_NAME[lang]}\n\nQuestion : ${question}`;
  const ex = excerptsFor(question + " " + pageTitle, pageUrl);

  const client = new Anthropic({ apiKey: env.ANTHROPIC_API_KEY });
  let stream;
  try {
    stream = client.messages.stream({
      model: MODEL_CHAT,
      max_tokens: CHAT_MAX_TOKENS,
      output_config: { effort: "low" },
      system: [
        { type: "text", text: SYSTEM_CHAT },
        { type: "text", text: siteMap(), cache_control: { type: "ephemeral" } },
      ],
      messages: [
        ...history,
        { role: "user", content: ex ? [{ type: "text", text: ex }, { type: "text", text: situation }]
                                    : [{ type: "text", text: situation }] },
      ],
    });
  } catch (error) {
    return reply(origin, 502, { code: "upstream" });
  }

  const { readable, writable } = new TransformStream();
  const writer = writable.getWriter();
  const enc = new TextEncoder();
  const send = (o) => writer.write(enc.encode("data: " + JSON.stringify(o) + "\n\n"));

  (async () => {
    try {
      for await (const event of stream) {
        if (event.type === "content_block_delta" && event.delta &&
            event.delta.type === "text_delta" && event.delta.text) {
          await send({ t: event.delta.text });
        }
      }
      const final = await stream.finalMessage();
      if (final.stop_reason === "refusal") await send({ code: "refused" });
      await send({ done: true, usage: final.usage ? {
        in: final.usage.input_tokens, cached: final.usage.cache_read_input_tokens,
        out: final.usage.output_tokens } : undefined });
    } catch (error) {
      let code = "server_error";
      if (error instanceof Anthropic.RateLimitError) code = "rate_limited";
      else if (error instanceof Anthropic.AuthenticationError) code = "server_key";
      else if (error instanceof Anthropic.APIError) code = "upstream";
      try { await send({ code }); } catch (e) {}
    } finally {
      try { await writer.close(); } catch (e) {}
    }
  })();

  return new Response(readable, {
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-store",
      ...cors(origin),
    },
  });
}


// ---------- la voz de Karla ----------
// Las respuestas de la IA se escriben en el momento, así que no están en el manifest de MP3
// del sitio: hay que sintetizarlas en vivo. Azure hace el trabajo con la clave del Worker.
// Mientras no exista el clon, habla una voz neuronal; el día que exista, basta con poner
// AZURE_VOICE_PROFILE y esta misma ruta usa la voz de Karla, sin tocar ninguna página.
const VOICE_MAX_CHARS = 1500;
const VOICE_BY_LANG = {
  fr: { voice: "fr-CA-SylvieNeural", locale: "fr-CA" },
  es: { voice: "es-MX-DaliaNeural", locale: "es-MX" },
  en: { voice: "en-US-AvaNeural", locale: "en-US" },
};
const VOICE_BASE_MODEL = "DragonLatestNeural";   // el modelo base que lleva el clon
const VOICE_FORMAT = "audio-24khz-48kbitrate-mono-mp3";
const VOICE_RATE = "-4%";

// El modelo escribe en markdown ligero; nada de eso debe leerse en voz alta.
function speakable(text) {
  return String(text)
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/`([^`]*)`/g, "$1")
    .replace(/\*\*([^*]*)\*\*/g, "$1")
    .replace(/\*([^*]*)\*/g, "$1")
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/https?:\/\/\S+/g, " ")
    .replace(/^\s*[-*•]\s+/gm, "")
    .replace(/[<>&]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function voiceSsml(text, lang, profile) {
  const pick = VOICE_BY_LANG[lang] || VOICE_BY_LANG.es;
  const body = `<prosody rate="${VOICE_RATE}">${text}</prosody>`;
  const inner = profile
    ? `<voice name="${VOICE_BASE_MODEL}"><mstts:ttsembedding speakerProfileId="${profile}">` +
      `${body}</mstts:ttsembedding></voice>`
    : `<voice name="${pick.voice}">${body}</voice>`;
  return '<speak version="1.0" xmlns="http://www.w3.org/2001/10/synthesis" ' +
    `xmlns:mstts="http://www.w3.org/2001/mstts" xml:lang="${pick.locale}">${inner}</speak>`;
}

async function voice(origin, env, body) {
  if (!env.AZURE_TTS_KEY || !env.AZURE_TTS_REGION) {
    return reply(origin, 503, { code: "no_voice" });
  }
  const text = speakable(body.text || "").slice(0, VOICE_MAX_CHARS);
  if (!text) return reply(origin, 400, { code: "bad_request" });
  const lang = VOICE_BY_LANG[body.lang] ? body.lang : "es";
  const ssml = voiceSsml(text, lang, env.AZURE_VOICE_PROFILE || "");

  let res;
  try {
    res = await fetch(
      `https://${env.AZURE_TTS_REGION}.tts.speech.microsoft.com/cognitiveservices/v1`,
      { method: "POST",
        headers: { "Ocp-Apim-Subscription-Key": env.AZURE_TTS_KEY,
                   "Content-Type": "application/ssml+xml",
                   "User-Agent": "course-site-tts",
                   "X-Microsoft-OutputFormat": VOICE_FORMAT },
        body: ssml });
  } catch (e) {
    return reply(origin, 502, { code: "upstream" });
  }
  if (!res.ok) {
    return reply(origin, res.status === 429 ? 429 : 502,
                 { code: res.status === 429 ? "rate_limited" : "upstream", status: res.status });
  }
  return new Response(res.body, {
    headers: { "Content-Type": "audio/mpeg", "Cache-Control": "no-store", ...cors(origin) },
  });
}

export default {
  async fetch(request, env) {
    const origin = request.headers.get("Origin") || "";
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors(origin) });
    if (request.method !== "POST") return reply(origin, 405, { code: "method_not_allowed" });
    if (!ALLOWED_ORIGINS.includes(origin)) return reply(origin, 403, { code: "forbidden_origin" });

    // per-visitor limit (Cloudflare rate-limiting binding, see wrangler.toml)
    if (env.LIMITER) {
      try {
        const ip = request.headers.get("CF-Connecting-IP") || "unknown";
        const { success } = await env.LIMITER.limit({ key: ip });
        if (!success) return reply(origin, 429, { code: "rate_limited" });
      } catch (e) { console.log("rate limiter unavailable:", String(e)); }
    }
    let body;
    try { body = await request.json(); } catch (e) { return reply(origin, 400, { code: "bad_request" }); }

    if (body.mode === "chat") return chat(origin, env, body);
    if (body.mode === "voice") return voice(origin, env, body);
    if (!env.ANTHROPIC_API_KEY) return reply(origin, 500, { code: "server_key", detail: "ANTHROPIC_API_KEY secret is not set" });

    const prompt = typeof body.prompt === "string" ? body.prompt : "";
    if (!prompt || prompt.length > MAX_PROMPT_CHARS) return reply(origin, 400, { code: "bad_request" });
    const effort = body.tier === "quick" ? "low" : "medium";
    const content = [];
    if (body.kb === true) {
      const query = (typeof body.query === "string" && body.query.trim() ? body.query : prompt).slice(0, MAX_QUERY_CHARS);
      content.push({ type: "text", text: courseContext(query) });
    }
    content.push({ type: "text", text: prompt });

    const client = new Anthropic({ apiKey: env.ANTHROPIC_API_KEY });
    try {
      const response = await client.beta.messages.create({
        model: MODEL,
        max_tokens: 16000,
        betas: ["server-side-fallback-2026-07-01"],
        fallbacks: "default",
        output_config: { effort },
        system: SYSTEM,
        messages: [{ role: "user", content }],
      });
      if (response.stop_reason === "refusal") return reply(origin, 200, { code: "refused" });
      let text = "";
      for (const block of response.content) if (block.type === "text") text += block.text;
      if (!text.trim()) return reply(origin, 200, { code: "empty_completion" });
      const data = extractJson(text);
      if (!data || typeof data !== "object") return reply(origin, 200, { code: "invalid_json" });
      if (data.error === "hors_sujet") return reply(origin, 200, { code: "refused" });
      return reply(origin, 200, { data });
    } catch (error) {
      if (error instanceof Anthropic.RateLimitError) return reply(origin, 429, { code: "rate_limited" });
      if (error instanceof Anthropic.AuthenticationError) return reply(origin, 500, { code: "server_key" });
      if (error instanceof Anthropic.APIConnectionError) return reply(origin, 502, { code: "upstream" });
      if (error instanceof Anthropic.APIError) return reply(origin, 502, { code: "upstream", status: error.status });
      console.log("unexpected error:", error);
      return reply(origin, 500, { code: "server_error", detail: String((error && error.name) || "") + ": " + String((error && error.message) || error).slice(0, 300) });
    }
  },
};
